export const DATABASE_ENGINES = [
    { "name": "Atomic", "syntax": "ENGINE = Atomic", "description": "The `Atomic` engine supports non-blocking `DROP TABLE` and `RENAME TABLE` queries, and atomic `EXCHANGE TABLES` queries. The `Atomic` database engine is used by default in open-source ClickHouse." },
    { "name": "Backup", "syntax": "ENGINE = Backup('database_name_inside_backup', Disk('disk_name', 'backup_name'))", "description": "Database backup allows to instantly attach table/database from backups in read-only mode." },
    { "name": "Cluster", "syntax": "ENGINE = Cluster('cluster_name', 'database')", "description": "The `Cluster` database engine provides real-time access to the tables of a database on a cluster from the server configuration. It is the named-cluster counterpart of the `Remote` database engine, exactly as the `cluster` table function relates to the `remote` table function." },
    { "name": "DataLakeCatalog", "syntax": "ENGINE = DataLakeCatalog('catalog_url'[, 'user', 'password']) SETTINGS catalog_type = '...'", "description": "The `DataLakeCatalog` database engine enables you to connect ClickHouse to external data catalogs and query open table format data without the need for data duplication. This transforms ClickHouse into a powerful query engine that works seamlessly with your existing data lake infrastructure." },
    { "name": "Dictionary", "syntax": "ENGINE = Dictionary", "description": "The `Dictionary` database engine exposes every configured dictionary as a read-only table. It is useful when a query needs to read or join dictionary data using ordinary table syntax." },
    { "name": "Filesystem", "syntax": "ENGINE = Filesystem([path])", "description": "The `Filesystem` database engine exposes files in a local directory as read-only tables. A table name is resolved as a path relative to the database directory and is read using the `file` table function." },
    { "name": "HDFS", "syntax": "ENGINE = HDFS([hdfs_host_and_root_path])", "description": "The `HDFS` database engine exposes files in HDFS as read-only tables. A table name is resolved through the `hdfs` table function." },
    { "name": "MaterializedPostgreSQL", "syntax": "ENGINE = MaterializedPostgreSQL('host:port', 'database', 'user', 'password')", "description": "Creates a ClickHouse database with tables from PostgreSQL database. Firstly, database with engine `MaterializedPostgreSQL` creates a snapshot of PostgreSQL database and loads required tables. Required tables can include any subset of tables from any subset of schemas from specified database." },
    { "name": "Memory", "syntax": "ENGINE = Memory", "description": "The `Memory` database engine keeps its metadata and table definitions only in memory. It is intended for temporary databases: the database and its tables are lost when the server stops or restarts." },
    { "name": "MySQL", "syntax": "ENGINE = MySQL('host:port', 'database', 'user', 'password')", "description": "Allows to connect to databases on a remote MySQL server and perform `INSERT` and `SELECT` queries to exchange data between ClickHouse and MySQL." },
    { "name": "Ordinary", "syntax": "ENGINE = Ordinary", "description": "The `Ordinary` database engine is the legacy database engine. It stores each table's metadata in a separate file and has been superseded by `Atomic`." },
    { "name": "Overlay", "syntax": "ENGINE = Overlay(db1[, db2, ...])", "description": "The `Overlay` database engine exposes the union of the tables of several existing databases." },
    { "name": "PostgreSQL", "syntax": "ENGINE = PostgreSQL('host:port', 'database', 'user', 'password'[, schema, use_table_cache])", "description": "Allows to connect to databases on a remote PostgreSQL server. Supports read and write operations (`SELECT` and `INSERT` queries) to exchange data between ClickHouse and PostgreSQL." },
    { "name": "Remote", "syntax": "ENGINE = Remote('addresses_expr', 'database'[, 'user'[, 'password']])", "description": "The `Remote` and `RemoteSecure` database engines provide real-time access to the tables of a database on a remote ClickHouse server over the native TCP protocol. They are the ClickHouse-to-ClickHouse counterparts of the `MySQL` and `PostgreSQL` database engines." },
    { "name": "RemoteSecure", "syntax": "ENGINE = RemoteSecure('addresses_expr', 'database'[, 'user'[, 'password']])", "description": "The `Remote` and `RemoteSecure` database engines provide real-time access to the tables of a database on a remote ClickHouse server over the native TCP protocol. They are the ClickHouse-to-ClickHouse counterparts of the `MySQL` and `PostgreSQL` database engines." },
    { "name": "Replicated", "syntax": "ENGINE = Replicated('zoo_path', 'shard_name', 'replica_name')", "description": "The engine is based on the Atomic engine. It supports replication of metadata via DDL log being written to ZooKeeper and executed on all of the replicas for a given database." },
    { "name": "S3", "syntax": "ENGINE = S3([config_or_url[, access_key_id, secret_access_key]])", "description": "The `S3` database engine exposes objects in Amazon S3 and S3-compatible object storage as read-only tables. A table name is resolved as an object URL through the `s3` table function." },
    { "name": "SQLite", "syntax": "ENGINE = SQLite('path_to_database_file')", "description": "Allows to connect to SQLite database and perform `INSERT` and `SELECT` queries to exchange data between ClickHouse and SQLite." },
    { "name": "URL", "syntax": "ENGINE = URL([base_url])", "description": "The `URL` database engine treats table names as URLs and exposes the data at those URLs as tables. It uses the `url` table function, which dispatches each URL to the appropriate backend, such as `file`, `s3`, HDFS, Azure Blob Storage, or HTTP." },
];
